#include <stdio.h>

int main(void) {
    int n, depth = 0, valid = 1;
    char line[256];

    if (scanf("%d", &n) != 1) return 0;
    getchar();

    for (int i = 0; i < n; i++) {
        if (fgets(line, sizeof(line), stdin) == NULL) break;

        for (int j = 0; line[j] != '\0'; j++) {
            if (line[j] == '{') {
                depth++;
            } else if (line[j] == '}') {
                depth--;
                if (depth < 0) valid = 0;
            }
        }
    }

    puts(valid && depth == 0 ? "S" : "N");
    return 0;
}
